def is_valid(number):
    clean = number.replace(" ", "").replace("-", "")

    if len(clean) < 2 or not all(c in "0123456789" for c in clean):
        return False

    total = 0
    for i, digit in enumerate(reversed(clean)):
        d = int(digit)
        if i % 2 == 1:
            d = d * 2
            if d > 9:
                d = d - 9
        total += d

    return total % 10 == 0


def check_digit(partial):
    clean = partial.replace(" ", "").replace("-", "")

    if len(clean) < 1 or not all(c in "0123456789" for c in clean):
        raise ValueError("Invalid partial string")

    for digit in range(10):
        candidate = clean + str(digit)
        if is_valid(candidate):
            return str(digit)

    raise ValueError("No valid check digit found")
